#include <memory>
#include <iostream>

// NOTE: auto_ptr is deprecated and should not be used.
void process_ptr(std::auto_ptr<int> p) {
    if (p.get()) {
        std::cout << "Processing value: " << *p << std::endl;
    }
    // Ownership transferred to p, which deletes it on exit.
}

int main() {
    std::auto_ptr<int> original(new int(42));

    // Ownership transfer (destructive copy):
    std::auto_ptr<int> stolen = original; 

    std::cout << "Stolen value: " << *stolen << std::endl;

    // original.get() is now nullptr. Accessing it is UB.
    // std::cout << *original; // DANGER!

    // Function call also transfers ownership:
    process_ptr(stolen);
    // stolen is now nullptr.
}
